import com.jimmy.bluepointer.DraftEditor;
public class DraftEditorTests {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args){DraftEditor e=new DraftEditor();e.set("香港",1);e.insert("的");check(e.text.equals("香的港")&&e.cursor==2,"Insert at caret");e.backspace();check(e.text.equals("香港")&&e.cursor==1,"Delete before caret");e.set("A😀B",3);e.move(-1,0);check(e.cursor==1,"Left over emoji");e.move(1,0);check(e.cursor==3,"Right over emoji");e.backspace();check(e.text.equals("AB")&&e.cursor==1,"Emoji deletion intact");e.set("A😀B",2);check(e.cursor==1,"Clamp surrogate selection");e.set("abcd\nxy\n12345",3);e.move(0,1);check(e.cursor==7,"Down clamps short line");e.move(0,1);check(e.cursor==10,"Down preserves column");e.move(0,-1);check(e.cursor==7,"Up preserves column");e.set("abc",0);e.backspace();e.move(-10,0);check(e.cursor==0&&e.text.equals("abc"),"Start boundary");e.move(10,0);check(e.cursor==3,"End boundary");e.set("香港",1);String text=e.text;int caret=e.cursor;e.set(text,caret);check(e.text.equals(text)&&e.cursor==caret,"State retained across redraw");System.out.println("PASS: caret insertion, backspace, emoji boundaries, vertical movement, edge bounds, state restoration.");}
}
